/* ============================================================
   허구의 아카이브 — 학급 창작 기록 시스템
   단원: 실재한 적 없는 유물 이미지로 구성한 허구의 아카이브 전시 (고1 미술, 8차시)
   학생: 학번+별명+4자리 코드로 입장, 창작 과정 기록지 작성 (자동 저장, 이어서 작성)
   교사: 관리자 코드로 입장, 진행 현황·기록 열람·루브릭 채점·분석·CSV 내보내기
   저장: window.storage (shared) — 학급 공용 데이터
   ============================================================ */

const store = {
  get: (k) => fbStore.get(k),
  set: (k, v) => fbStore.set(k, v),
};

/* 미디어(사진·음성·스케치·영상) 저장 계층 — Firestore media 컬렉션.
   문서 이름은 {소유자}_{필드키} 형식이어야 보안 규칙이 앞부분으로 소유자를 판별한다. */
const mediaStore = {
  get: (owner, ref) => fbStore.get("media:" + owner + "_" + ref),
  put: (owner, ref, data) => fbStore.set("media:" + owner + "_" + ref, data),
  remove: (owner, ref) => fbStore.remove("media:" + owner + "_" + ref),
};

const now = () => new Date().toISOString();
const fmtDur = (sec) => {
  const s = Math.max(0, Math.round(sec || 0));
  const m = Math.floor(s / 60);
  return m ? m + "분 " + (s % 60 ? s % 60 + "초" : "") : s + "초";
};
const fmtTime = (iso) => {
  if (!iso) return "-";
  const d = new Date(iso);
  return `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
};

