/* 이 단원이 서 있는 자리 — 학생이 자기 선택을 견주어 볼 기준점 */
const UNIT_MODES = ["indirect", "parafiction", "forensic"];

const cardsOf = (src) => (src === "obs" ? OBS_METHODS : ENGAGE_MODES);
const cardLabel = (src, k) => (cardsOf(src).find((c) => c.k === k) || {}).label || "";

