          "뒤샹을 옹호하는 익명의 글(뒤샹 자신이 관여한 것으로 알려져 있습니다)은 이렇게 주장했습니다. Mutt 씨가 그것을 직접 만들었는가는 중요하지 않다. 그는 그것을 선택했다. 일상의 사물을 골라 새 제목과 관점을 부여해 원래의 쓸모가 사라지게 했고, 그 사물에 대한 새로운 생각을 만들어 냈다. 여기서 작가의 일은 제작에서 선택으로 옮겨 갑니다. 이런 작업 방식을 레디메이드(ready-made)라고 부릅니다.",
