    L.push("");
    L.push(mdHead(["관찰 절차", "이론적 출처", "잘 잡아내는 것", "놓치는 것"]));
    OBS_METHODS.forEach((m) => L.push(mdRow([m.label, m.from, m.good, m.miss])));
    L.push("");
    L.push("T4에서 학생은 사회참여 미술이 사회를 드러내 온 여덟 갈래를 읽고 자기 작업이 설 자리를 정한다. 같은 문제를 다뤄도 갈래에 따라 관람자가 하는 일과 작가가 지는 책임이 달라지므로, 고른 이유·접은 갈래의 이유·그 갈래에 딸린 위험을 다룰 방도·이 단원의 형식(유물 기록 사진과 명제표)으로 실현할 방법을 함께 쓰게 했다. 이 단원의 결과물 자체는 가림과 우회 · 허구와 파라픽션 · 증거와 포렌식 세 갈래를 겹쳐 놓은 형식이며, 학생이 다른 갈래를 골랐을 때 그 갈래가 형식의 어느 요소를 맡을지 스스로 정하도록 했다.");
